/** One delegated handler for the whole provider grid — the imported tiles keep
 *  their exact markup and only gain a click target. */
function useGameGridClick() {
  const { notify, category } = useSite();
  return (event: MouseEvent<HTMLDivElement>) => {
    const tile = (event.target as HTMLElement).closest('[data-name="game cover"]');
    if (!tile) return;
    notify(`กำลังเปิดเกม ${CATEGORY_LABELS[category]} — ONE BX Studio`);
  };
}

